CREATE TABLE "hr_payrolls" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "user_profile_id" bigint NOT NULL, "organization_id" bigint NOT NULL, "cycle_start_date" date NOT NULL, "cycle_end_date" date NOT NULL, "base_salary" numeric(12, 2) NOT NULL, "bonuses" numeric(12, 2) NOT NULL, "advance" numeric(12, 2) NOT NULL, "deductions" numeric(12, 2) NOT NULL, "net_pay" numeric(12, 2) NOT NULL, "status" varchar(20) NOT NULL, "processed_on" timestamp with time zone NOT NULL);
CREATE TABLE "django_migrations" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "app" varchar(255) NOT NULL, "name" varchar(255) NOT NULL, "applied" timestamp with time zone NOT NULL);

